// FreeLang GPT: Phase 3 - Neural Network Layers
// ==================================================
// Core neural network components
// Status: 🟢 Implementation (Phase 3 Pilot)

module nn

import tensor
import autograd
import math
import arrays

// ==================================================
// 1. LINEAR LAYER RECORD & INITIALIZATION
// ==================================================

// Linear layer: y = x @ W^T + b
record Linear {
  weight: Variable,       // shape: [out_features, in_features]
  bias: Variable,         // shape: [out_features]
  in_features: Int,
  out_features: Int
}

// Initialize linear layer with Xavier initialization
function linear_init(in_features: Int, out_features: Int, seed: Int) -> Linear = {
  // Xavier initialization: scale = sqrt(2 / (in + out))
  let scale = math.sqrt(2.0 / as_float(in_features + out_features))

  // Weight tensor: [out_features, in_features]
  let weight_tensor = randn_tensor([out_features, in_features], seed)
  let weight_scaled = tensor_scale(weight_tensor, scale)

  // Bias tensor: [out_features]
  let bias_tensor = zeros_tensor([out_features])

  let weight_var = Variable {
    data: weight_scaled,
    grad: None,
    requires_grad: true,
    node_id: 0
  }

  let bias_var = Variable {
    data: bias_tensor,
    grad: None,
    requires_grad: true,
    node_id: 1
  }

  Linear {
    weight: weight_var,
    bias: bias_var,
    in_features: in_features,
    out_features: out_features
  }
}

// ==================================================
// 2. LINEAR LAYER FORWARD PASS
// ==================================================

// Forward pass: y = x @ W^T + b
// Input: x of shape [batch_size, in_features]
// Weight: W of shape [out_features, in_features]
// Output: y of shape [batch_size, out_features]
function forward_linear(layer: Linear, x: Tensor) -> Tensor = {
  // Transpose weight to [in_features, out_features] for matmul
  let w_t = transpose_2d(layer.weight.data)

  // Matrix multiply: x @ W^T = [batch, in] @ [in, out] = [batch, out]
  let output = matmul_2d(x, w_t)

  // Add bias: broadcast bias across batch dimension
  let batch_size = output.shape[0]
  let result = zeros_tensor([batch_size, layer.out_features])

  fold_range(0, batch_size, result, fn(res, i) -> {
    fold_range(0, layer.out_features, res, fn(res2, j) -> {
      let out_val = tensor_get_2d(output, i, j)
      let bias_val = tensor_get_2d(layer.bias.data, j, 0)
      tensor_set_2d(res2, i, j, out_val + bias_val)
      res2
    })
  })
}

// ==================================================
// 3. LAYER NORMALIZATION
// ==================================================

record LayerNorm {
  weight: Variable,       // shape: [normalized_shape]
  bias: Variable,         // shape: [normalized_shape]
  normalized_shape: Int,
  eps: Float              // epsilon for numerical stability
}

// Initialize layer norm
function layer_norm_init(normalized_shape: Int, eps: Float) -> LayerNorm = {
  let weight_tensor = ones_tensor([normalized_shape])
  let bias_tensor = zeros_tensor([normalized_shape])

  let weight_var = Variable {
    data: weight_tensor,
    grad: None,
    requires_grad: true,
    node_id: 0
  }

  let bias_var = Variable {
    data: bias_tensor,
    grad: None,
    requires_grad: true,
    node_id: 1
  }

  LayerNorm {
    weight: weight_var,
    bias: bias_var,
    normalized_shape: normalized_shape,
    eps: eps
  }
}

// Forward pass: (x - mean) / sqrt(var + eps) * gamma + beta
function forward_layer_norm(ln: LayerNorm, x: Tensor) -> Tensor = {
  let batch_size = x.shape[0]
  let feature_size = x.shape[1]

  // Compute mean for each sample
  let means = zeros_tensor([batch_size])
  fold_range(0, batch_size, means, fn(acc_mean, i) -> {
    let sum = fold_range(0, feature_size, 0.0, fn(acc_sum, j) -> {
      acc_sum + tensor_get_2d(x, i, j)
    })
    let mean = sum / as_float(feature_size)
    tensor_set_2d(acc_mean, i, 0, mean)
    acc_mean
  })

  // Compute variance for each sample
  let variances = zeros_tensor([batch_size])
  fold_range(0, batch_size, variances, fn(acc_var, i) -> {
    let mean = tensor_get_2d(means, i, 0)
    let sum = fold_range(0, feature_size, 0.0, fn(acc_sum, j) -> {
      let val = tensor_get_2d(x, i, j)
      let diff = val - mean
      acc_sum + (diff * diff)
    })
    let variance = sum / as_float(feature_size)
    tensor_set_2d(acc_var, i, 0, variance)
    acc_var
  })

  // Normalize and apply scale/shift
  let result = zeros_tensor([batch_size, feature_size])
  fold_range(0, batch_size, result, fn(acc_res, i) -> {
    let mean = tensor_get_2d(means, i, 0)
    let variance = tensor_get_2d(variances, i, 0)
    let std_dev = math.sqrt(variance + ln.eps)

    fold_range(0, feature_size, acc_res, fn(acc_res2, j) -> {
      let val = tensor_get_2d(x, i, j)
      let normalized = (val - mean) / std_dev
      let weight_j = tensor_get_2d(ln.weight.data, j, 0)
      let bias_j = tensor_get_2d(ln.bias.data, j, 0)
      let output = (normalized * weight_j) + bias_j
      tensor_set_2d(acc_res2, i, j, output)
      acc_res2
    })
  })
}

// ==================================================
// 4. ACTIVATION FUNCTIONS
// ==================================================

// ReLU: max(0, x)
function relu(x: Tensor) -> Tensor = {
  let result_data = []
  let result = fold_range(0, x.size, result_data, fn(acc, i) -> {
    let val = x.data[i]
    append(acc, if val > 0.0 { val } else { 0.0 })
  })

  Tensor {
    data: result,
    shape: x.shape,
    strides: x.strides,
    ndim: x.ndim,
    size: x.size
  }
}

// GELU approximation: x * Phi(x)
// Using tanh approximation: 0.5*x*(1 + tanh(sqrt(2/pi)*(x + 0.044715*x^3)))
function gelu(x: Tensor) -> Tensor = {
  let cdf_coeff = 0.7978845608028654  // sqrt(2/pi)
  let cubic_coeff = 0.044715

  let result_data = []
  let result = fold_range(0, x.size, result_data, fn(acc, i) -> {
    let val = x.data[i]
    let cubic = val * val * val
    let inner = val + (cubic_coeff * cubic)
    let cdf = 0.5 * (1.0 + math.tanh(cdf_coeff * inner))
    append(acc, val * cdf)
  })

  Tensor {
    data: result,
    shape: x.shape,
    strides: x.strides,
    ndim: x.ndim,
    size: x.size
  }
}

// Softmax with numerical stability (subtract max)
function softmax(x: Tensor) -> Tensor = {
  // Only works for 2D tensors where softmax is applied column-wise
  if x.ndim != 2 {
    x  // Return unchanged if not 2D
  } else {
    let batch_size = x.shape[0]
    let num_classes = x.shape[1]

    // Find max for each row
    let maxes = zeros_tensor([batch_size])
    fold_range(0, batch_size, maxes, fn(acc_max, i) -> {
      let row_max = fold_range(0, num_classes, -99999.0, fn(acc_rm, j) -> {
        let val = tensor_get_2d(x, i, j)
        if val > acc_rm { val } else { acc_rm }
      })
      tensor_set_2d(acc_max, i, 0, row_max)
      acc_max
    })

    // Compute exp(x_ij - max_i) and sum
    let exp_sums = zeros_tensor([batch_size])
    let exp_x = zeros_tensor([batch_size, num_classes])

    fold_range(0, batch_size, exp_x, fn(acc_exp, i) -> {
      let max_val = tensor_get_2d(maxes, i, 0)
      let sum = fold_range(0, num_classes, 0.0, fn(acc_sum, j) -> {
        let val = tensor_get_2d(x, i, j)
        let exp_val = math.exp(val - max_val)
        tensor_set_2d(acc_exp, i, j, exp_val)
        acc_sum + exp_val
      })
      tensor_set_2d(exp_sums, i, 0, sum)
      acc_exp
    })

    // Divide by sum to get probabilities
    fold_range(0, batch_size, exp_x, fn(acc_final, i) -> {
      let sum = tensor_get_2d(exp_sums, i, 0)
      fold_range(0, num_classes, acc_final, fn(acc_final2, j) -> {
        let exp_val = tensor_get_2d(exp_x, i, j)
        tensor_set_2d(acc_final2, i, j, exp_val / sum)
        acc_final2
      })
    })
  }
}

// ==================================================
// 5. HELPER FUNCTIONS
// ==================================================

// Transpose 2D tensor for matmul operations
function transpose_2d(t: Tensor) -> Tensor = {
  let rows = t.shape[0]
  let cols = t.shape[1]
  let result = zeros_tensor([cols, rows])

  fold_range(0, rows, result, fn(acc, i) -> {
    fold_range(0, cols, acc, fn(acc2, j) -> {
      let val = tensor_get_2d(t, i, j)
      tensor_set_2d(acc2, j, i, val)
      acc2
    })
  })
}

// ==================================================
// 6. TESTS
// ==================================================

function test_linear_init() -> Bool = {
  let layer = linear_init(10, 5, 42)
  layer.in_features == 10 && layer.out_features == 5 &&
  layer.weight.data.shape[0] == 5 &&
  layer.weight.data.shape[1] == 10
}

function test_linear_forward() -> Bool = {
  let layer = linear_init(3, 2, 42)
  let x = ones_tensor([2, 3])  // batch=2, in_features=3
  let y = forward_linear(layer, x)

  y.shape[0] == 2 && y.shape[1] == 2
}

function test_relu() -> Bool = {
  let t = zeros_tensor([2, 2])
  tensor_set_2d(t, 0, 0, 1.0)
  tensor_set_2d(t, 0, 1, -0.5)

  let result = relu(t)
  tensor_get_2d(result, 0, 0) == 1.0 &&
  tensor_get_2d(result, 0, 1) == 0.0
}

function test_gelu() -> Bool = {
  let t = zeros_tensor([1, 1])
  let result = gelu(t)

  // GELU(0) ≈ 0
  let gelu_zero = tensor_get_2d(result, 0, 0)
  gelu_zero > -0.01 && gelu_zero < 0.01
}

function test_softmax() -> Bool = {
  let t = ones_tensor([1, 3])
  let result = softmax(t)

  // All equal values → equal probability = 1/3
  let sum = tensor_get_2d(result, 0, 0) +
            tensor_get_2d(result, 0, 1) +
            tensor_get_2d(result, 0, 2)

  sum > 0.99 && sum < 1.01
}

function test_layer_norm_init() -> Bool = {
  let ln = layer_norm_init(10, 1e-5)
  ln.normalized_shape == 10 &&
  ln.weight.data.shape[0] == 10 &&
  tensor_get_2d(ln.weight.data, 0, 0) == 1.0
}

function test_layer_norm_forward() -> Bool = {
  let ln = layer_norm_init(2, 1e-5)
  let x = zeros_tensor([1, 2])
  tensor_set_2d(x, 0, 0, 1.0)
  tensor_set_2d(x, 0, 1, 3.0)

  let result = forward_layer_norm(ln, x)
  result.shape[0] == 1 && result.shape[1] == 2
}

function test_transpose() -> Bool = {
  let t = zeros_tensor([2, 3])
  tensor_set_2d(t, 0, 0, 1.0)
  tensor_set_2d(t, 0, 1, 2.0)
  tensor_set_2d(t, 1, 0, 3.0)

  let t_T = transpose_2d(t)

  tensor_get_2d(t_T, 0, 0) == 1.0 &&
  tensor_get_2d(t_T, 1, 0) == 2.0 &&
  tensor_get_2d(t_T, 0, 1) == 3.0
}

// ==================================================
// RUN ALL TESTS
// ==================================================

function run_all_tests() -> Bool = {
  let t1 = test_linear_init()
  let t2 = test_linear_forward()
  let t3 = test_relu()
  let t4 = test_gelu()
  let t5 = test_softmax()
  let t6 = test_layer_norm_init()
  let t7 = test_layer_norm_forward()
  let t8 = test_transpose()

  t1 && t2 && t3 && t4 && t5 && t6 && t7 && t8
}

// ==================================================
// END OF NN MODULE
// ==================================================

