// FreeLang GPT: Phase 4 - Attention Mechanism
// ==================================================
// Multi-Head Attention with Causal Masking
// Status: 🟢 Implementation (Phase 4 Pilot)

module attention

import tensor
import nn
import math
import arrays

// ==================================================
// 1. MULTI-HEAD ATTENTION RECORD
// ==================================================

record MultiHeadAttention {
  num_heads: Int,           // Number of attention heads
  d_model: Int,             // Total embedding dimension
  d_head: Int,              // Dimension per head (d_model / num_heads)
  w_q: Linear,              // Query projection
  w_k: Linear,              // Key projection
  w_v: Linear,              // Value projection
  w_o: Linear,              // Output projection
  use_causal_mask: Bool     // Apply causal mask for AR models
}

// ==================================================
// 2. ATTENTION INITIALIZATION
// ==================================================

// Initialize multi-head attention
function multi_head_attention_init(d_model: Int, num_heads: Int, use_causal: Bool, seed: Int) -> MultiHeadAttention = {
  // Validate d_model is divisible by num_heads
  let d_head = d_model / num_heads

  // Initialize projection layers
  let w_q = linear_init(d_model, d_model, seed)
  let w_k = linear_init(d_model, d_model, seed + 1)
  let w_v = linear_init(d_model, d_model, seed + 2)
  let w_o = linear_init(d_model, d_model, seed + 3)

  MultiHeadAttention {
    num_heads: num_heads,
    d_model: d_model,
    d_head: d_head,
    w_q: w_q,
    w_k: w_k,
    w_v: w_v,
    w_o: w_o,
    use_causal_mask: use_causal
  }
}

// ==================================================
// 3. CAUSAL MASK GENERATION
// ==================================================

// Create causal mask: lower triangular matrix
// Shape: [seq_len, seq_len]
// Returns -inf (actually -9999.0) for upper triangle
function make_causal_mask(seq_len: Int) -> Tensor = {
  let mask = zeros_tensor([seq_len, seq_len])

  fold_range(0, seq_len, mask, fn(acc, i) -> {
    fold_range(0, seq_len, acc, fn(acc2, j) -> {
      // Mask future positions: j > i → -9999
      let mask_val = if j > i { -9999.0 } else { 0.0 }
      tensor_set_2d(acc2, i, j, mask_val)
      acc2
    })
  })
}

// ==================================================
// 4. ATTENTION COMPUTATION
// ==================================================

// Scaled dot-product attention
// attention(Q, K, V) = softmax(Q @ K^T / sqrt(d_k)) @ V
function scaled_dot_product_attention(q: Tensor, k: Tensor, v: Tensor, d_k: Float, mask: Option[Tensor]) -> Tensor = {
  // Q: [batch, seq_len, d_model]
  // K: [batch, seq_len, d_model]
  // V: [batch, seq_len, d_model]
  // Returns: [batch, seq_len, d_model]

  let batch_size = q.shape[0]
  let seq_len_q = q.shape[1]
  let seq_len_k = k.shape[1]

  // Step 1: Compute Q @ K^T / sqrt(d_k)
  let k_t = transpose_2d(k)
  let scores = matmul_2d(q, k_t)  // [batch, seq_len_q, seq_len_k]
  let scale_factor = 1.0 / math.sqrt(d_k)
  let scaled_scores = tensor_scale(scores, scale_factor)

  // Step 2: Apply mask if provided
  let masked_scores = match mask {
    Some(m) -> {
      fold_range(0, batch_size, scaled_scores, fn(acc, b) -> {
        fold_range(0, seq_len_q, acc, fn(acc2, i) -> {
          fold_range(0, seq_len_k, acc2, fn(acc3, j) -> {
            let score = tensor_get_2d(acc3, i, j)
            let mask_val = tensor_get_2d(m, i, j)
            let masked = score + mask_val  // Add -9999 to mask future
            tensor_set_2d(acc3, i, j, masked)
            acc3
          })
        })
      })
    },
    None -> scaled_scores
  }

  // Step 3: Apply softmax
  let attention_weights = softmax(masked_scores)

  // Step 4: Multiply by V
  let output = matmul_2d(attention_weights, v)
  output
}

// ==================================================
// 5. HEAD SPLITTING & MERGING
// ==================================================

// Split input into multiple heads
// Input: [batch, seq_len, d_model]
// Output: [batch, num_heads, seq_len, d_head]
// Returns: flattened to [batch*num_heads, seq_len, d_head] for processing
function split_heads(x: Tensor, num_heads: Int, d_head: Int) -> Tensor = {
  let batch_size = x.shape[0]
  let seq_len = x.shape[1]

  // Reshape [batch, seq_len, d_model] → [batch, seq_len, num_heads, d_head]
  // Then rearrange to [batch, num_heads, seq_len, d_head]
  // Flattened to [batch*num_heads, seq_len, d_head]
  let result = zeros_tensor([batch_size * num_heads, seq_len, d_head])

  fold_range(0, batch_size, result, fn(acc_b, b) -> {
    fold_range(0, seq_len, acc_b, fn(acc_s, s) -> {
      fold_range(0, num_heads, acc_s, fn(acc_h, h) -> {
        fold_range(0, d_head, acc_h, fn(acc_d, d) -> {
          // Source: x[b, s, h*d_head + d]
          let src_col = h * d_head + d
          let src_val = tensor_get_2d(x, s, src_col)
          // Dest: result[b*num_heads + h, s, d]
          let dest_row = b * num_heads + h
          tensor_set_2d(acc_d, dest_row, s, d, src_val)
          acc_d
        })
      })
    })
  })
}

// Merge heads back
// Input: [batch*num_heads, seq_len, d_head]
// Output: [batch, seq_len, d_model]
function merge_heads(x: Tensor, batch_size: Int, num_heads: Int, d_head: Int, seq_len: Int) -> Tensor = {
  let d_model = d_head * num_heads
  let result = zeros_tensor([batch_size, seq_len, d_model])

  fold_range(0, batch_size, result, fn(acc_b, b) -> {
    fold_range(0, seq_len, acc_b, fn(acc_s, s) -> {
      fold_range(0, num_heads, acc_s, fn(acc_h, s) -> {
        fold_range(0, d_head, acc_h, fn(acc_d, d) -> {
          // Source: x[b*num_heads + h, s, d]
          let src_row = b * num_heads + acc_h
          let src_val = tensor_get_2d(x, src_row, d, s)
          // Dest: result[b, s, h*d_head + d]
          let dest_col = acc_h * d_head + d
          tensor_set_2d(acc_d, s, dest_col, src_val)
          acc_d
        })
      })
    })
  })
}

// ==================================================
// 6. FORWARD PASS
// ==================================================

// Forward pass: Multi-Head Attention
function forward_mha(mha: MultiHeadAttention, x: Tensor) -> Tensor = {
  let batch_size = x.shape[0]
  let seq_len = x.shape[1]
  let d_model = mha.d_model
  let num_heads = mha.num_heads
  let d_head = mha.d_head

  // Step 1: Linear projections
  let q = forward_linear(mha.w_q, x)  // [batch, seq_len, d_model]
  let k = forward_linear(mha.w_k, x)  // [batch, seq_len, d_model]
  let v = forward_linear(mha.w_v, x)  // [batch, seq_len, d_model]

  // Step 2: Split into heads
  let q_heads = split_heads(q, num_heads, d_head)    // [batch*num_heads, seq_len, d_head]
  let k_heads = split_heads(k, num_heads, d_head)    // [batch*num_heads, seq_len, d_head]
  let v_heads = split_heads(v, num_heads, d_head)    // [batch*num_heads, seq_len, d_head]

  // Step 3: Apply attention with optional causal mask
  let mask = if mha.use_causal_mask { Some(make_causal_mask(seq_len)) } else { None }

  let attention_output = scaled_dot_product_attention(
    q_heads,
    k_heads,
    v_heads,
    as_float(d_head),
    mask
  )  // [batch*num_heads, seq_len, d_head]

  // Step 4: Merge heads
  let merged = merge_heads(attention_output, batch_size, num_heads, d_head, seq_len)  // [batch, seq_len, d_model]

  // Step 5: Output projection
  let output = forward_linear(mha.w_o, merged)  // [batch, seq_len, d_model]

  output
}

// ==================================================
// 7. UTILITY FUNCTIONS
// ==================================================

// Transpose 2D tensor
function transpose_2d(t: Tensor) -> Tensor = {
  let rows = t.shape[0]
  let cols = t.shape[1]
  let result = zeros_tensor([cols, rows])

  fold_range(0, rows, result, fn(acc, i) -> {
    fold_range(0, cols, acc, fn(acc2, j) -> {
      let val = tensor_get_2d(t, i, j)
      tensor_set_2d(acc2, j, i, val)
      acc2
    })
  })
}

// Softmax activation
function softmax(x: Tensor) -> Tensor = {
  if x.ndim != 2 {
    x
  } else {
    let batch_size = x.shape[0]
    let num_classes = x.shape[1]

    // Find max for numerical stability
    let maxes = zeros_tensor([batch_size])
    fold_range(0, batch_size, maxes, fn(acc_max, i) -> {
      let row_max = fold_range(0, num_classes, -99999.0, fn(acc_rm, j) -> {
        let val = tensor_get_2d(x, i, j)
        if val > acc_rm { val } else { acc_rm }
      })
      tensor_set_2d(acc_max, i, 0, row_max)
      acc_max
    })

    // Compute exp(x - max) and sum
    let exp_sums = zeros_tensor([batch_size])
    let exp_x = zeros_tensor([batch_size, num_classes])

    fold_range(0, batch_size, exp_x, fn(acc_exp, i) -> {
      let max_val = tensor_get_2d(maxes, i, 0)
      let sum = fold_range(0, num_classes, 0.0, fn(acc_sum, j) -> {
        let val = tensor_get_2d(x, i, j)
        let exp_val = math.exp(val - max_val)
        tensor_set_2d(acc_exp, i, j, exp_val)
        acc_sum + exp_val
      })
      tensor_set_2d(exp_sums, i, 0, sum)
      acc_exp
    })

    // Normalize
    fold_range(0, batch_size, exp_x, fn(acc_final, i) -> {
      let sum = tensor_get_2d(exp_sums, i, 0)
      fold_range(0, num_classes, acc_final, fn(acc_final2, j) -> {
        let exp_val = tensor_get_2d(exp_x, i, j)
        tensor_set_2d(acc_final2, i, j, exp_val / sum)
        acc_final2
      })
    })
  }
}

// ==================================================
// 8. TESTS
// ==================================================

function test_mha_init() -> Bool = {
  let mha = multi_head_attention_init(64, 8, true, 42)
  mha.d_model == 64 && mha.num_heads == 8 && mha.d_head == 8
}

function test_causal_mask() -> Bool = {
  let mask = make_causal_mask(3)
  // Check lower triangle is 0, upper is -9999
  tensor_get_2d(mask, 0, 0) == 0.0 &&
  tensor_get_2d(mask, 1, 0) == 0.0 &&
  tensor_get_2d(mask, 0, 1) == -9999.0 &&
  tensor_get_2d(mask, 1, 2) == -9999.0
}

function test_causal_mask_square() -> Bool = {
  let mask = make_causal_mask(4)
  let size = mask.shape[0]
  size == 4 && mask.shape[1] == 4
}

function test_scaled_attention_shape() -> Bool = {
  let q = ones_tensor([2, 4, 8])
  let k = ones_tensor([2, 4, 8])
  let v = ones_tensor([2, 4, 8])

  let output = scaled_dot_product_attention(q, k, v, 8.0, None)
  output.shape[0] == 2 && output.shape[1] == 4 && output.shape[2] == 8
}

function test_scaled_attention_with_mask() -> Bool = {
  let q = ones_tensor([2, 3, 8])
  let k = ones_tensor([2, 3, 8])
  let v = ones_tensor([2, 3, 8])
  let mask = Some(make_causal_mask(3))

  let output = scaled_dot_product_attention(q, k, v, 8.0, mask)
  output.shape[0] == 2 && output.shape[1] == 3
}

function test_split_heads() -> Bool = {
  let x = ones_tensor([2, 4, 8])  // [batch=2, seq_len=4, d_model=8]
  let result = split_heads(x, 2, 4)  // [batch*num_heads=4, seq_len=4, d_head=4]

  result.shape[0] == 4 && result.shape[1] == 4 && result.shape[2] == 4
}

function test_mha_forward() -> Bool = {
  let mha = multi_head_attention_init(64, 8, false, 42)
  let x = ones_tensor([2, 4, 64])  // [batch=2, seq_len=4, d_model=64]

  let output = forward_mha(mha, x)
  output.shape[0] == 2 && output.shape[1] == 4 && output.shape[2] == 64
}

function test_mha_forward_causal() -> Bool = {
  let mha = multi_head_attention_init(32, 4, true, 42)
  let x = ones_tensor([1, 8, 32])

  let output = forward_mha(mha, x)
  output.shape[0] == 1 && output.shape[1] == 8 && output.shape[2] == 32
}

function test_transpose() -> Bool = {
  let t = zeros_tensor([3, 4])
  tensor_set_2d(t, 0, 0, 1.0)
  tensor_set_2d(t, 1, 2, 5.0)

  let t_T = transpose_2d(t)
  tensor_get_2d(t_T, 0, 0) == 1.0 &&
  tensor_get_2d(t_T, 2, 1) == 5.0
}

function test_softmax() -> Bool = {
  let x = ones_tensor([2, 4])
  let result = softmax(x)

  let sum = tensor_get_2d(result, 0, 0) +
            tensor_get_2d(result, 0, 1) +
            tensor_get_2d(result, 0, 2) +
            tensor_get_2d(result, 0, 3)

  sum > 0.99 && sum < 1.01
}

// ==================================================
// RUN ALL TESTS
// ==================================================

function run_all_tests() -> Bool = {
  let t1 = test_mha_init()
  let t2 = test_causal_mask()
  let t3 = test_causal_mask_square()
  let t4 = test_scaled_attention_shape()
  let t5 = test_scaled_attention_with_mask()
  let t6 = test_split_heads()
  let t7 = test_mha_forward()
  let t8 = test_mha_forward_causal()
  let t9 = test_transpose()
  let t10 = test_softmax()

  t1 && t2 && t3 && t4 && t5 && t6 && t7 && t8 && t9 && t10
}

// ==================================================
// END OF ATTENTION MODULE
// ==================================================

