// FreeLang GPT: Phase 5 - Transformer Blocks
// ==================================================
// Core transformer architecture components
// Status: 🟢 Implementation (Phase 5 Pilot)

module transformer

import tensor
import nn
import attention
import math
import arrays

// ==================================================
// 1. TRANSFORMER BLOCK RECORD
// ==================================================

record FFN {
  fc1: Linear,              // d_model -> 4*d_model
  fc2: Linear               // 4*d_model -> d_model
}

record TransformerBlock {
  mha: MultiHeadAttention,
  ln1: LayerNorm,
  ffn: FFN,
  ln2: LayerNorm
}

record GPTConfig {
  vocab_size: Int,
  d_model: Int,
  num_heads: Int,
  num_layers: Int,
  max_seq_len: Int
}

record GPTModel {
  token_embed: Variable,    // [vocab_size, d_model]
  pos_embed: Variable,      // [max_seq_len, d_model]
  blocks: Array[TransformerBlock],
  ln_final: LayerNorm,
  lm_head: Linear           // d_model -> vocab_size
}

// ==================================================
// 2. TRANSFORMER BLOCK INITIALIZATION
// ==================================================

// Initialize FFN layer
function ffn_init(d_model: Int, seed: Int) -> FFN = {
  let fc1 = linear_init(d_model, 4 * d_model, seed)
  let fc2 = linear_init(4 * d_model, d_model, seed + 1)

  FFN {
    fc1: fc1,
    fc2: fc2
  }
}

// Initialize transformer block
function transformer_block_init(d_model: Int, num_heads: Int, use_causal: Bool, seed: Int) -> TransformerBlock = {
  let mha = multi_head_attention_init(d_model, num_heads, use_causal, seed)
  let ln1 = layer_norm_init(d_model, 1e-5)
  let ffn = ffn_init(d_model, seed + 10)
  let ln2 = layer_norm_init(d_model, 1e-5)

  TransformerBlock {
    mha: mha,
    ln1: ln1,
    ffn: ffn,
    ln2: ln2
  }
}

// ==================================================
// 3. TRANSFORMER BLOCK FORWARD PASS
// ==================================================

// FFN forward pass: x -> ReLU(x @ W1) @ W2
function forward_ffn(ffn: FFN, x: Tensor) -> Tensor = {
  let hidden = forward_linear(ffn.fc1, x)
  let activated = gelu(hidden)
  let output = forward_linear(ffn.fc2, activated)
  output
}

// Transformer block forward pass (Pre-LN architecture)
// x -> x + MHA(LN(x))
// -> x + FFN(LN(x))
function forward_block(block: TransformerBlock, x: Tensor) -> Tensor = {
  // Self-attention branch
  let ln1_output = forward_layer_norm(block.ln1, x)
  let mha_output = forward_mha(block.mha, ln1_output)
  let x_after_mha = tensor_add(x, mha_output)  // Residual connection

  // FFN branch
  let ln2_output = forward_layer_norm(block.ln2, x_after_mha)
  let ffn_output = forward_ffn(block.ffn, ln2_output)
  let output = tensor_add(x_after_mha, ffn_output)  // Residual connection

  output
}

// ==================================================
// 4. GPT MODEL INITIALIZATION
// ==================================================

// Initialize GPT model
function gpt_init(config: GPTConfig, seed: Int) -> GPTModel = {
  // Token embedding: [vocab_size, d_model]
  let token_embed_tensor = randn_tensor([config.vocab_size, config.d_model], seed)
  let token_embed = Variable {
    data: token_embed_tensor,
    grad: None,
    requires_grad: true,
    node_id: 0
  }

  // Positional embedding: [max_seq_len, d_model]
  let pos_embed_tensor = randn_tensor([config.max_seq_len, config.d_model], seed + 1)
  let pos_embed = Variable {
    data: pos_embed_tensor,
    grad: None,
    requires_grad: true,
    node_id: 1
  }

  // Transformer blocks
  let blocks = fold_range(0, config.num_layers, [], fn(acc, i) -> {
    let block = transformer_block_init(config.d_model, config.num_heads, true, seed + 100 + i)
    append(acc, block)
  })

  // Final layer norm
  let ln_final = layer_norm_init(config.d_model, 1e-5)

  // LM head
  let lm_head = linear_init(config.d_model, config.vocab_size, seed + 1000)

  GPTModel {
    token_embed: token_embed,
    pos_embed: pos_embed,
    blocks: blocks,
    ln_final: ln_final,
    lm_head: lm_head
  }
}

// ==================================================
// 5. GPT FORWARD PASS
// ==================================================

// Get token embeddings
function get_token_embed(model: GPTModel, token_ids: Tensor) -> Tensor = {
  let batch_size = token_ids.shape[0]
  let seq_len = token_ids.shape[1]
  let d_model = model.token_embed.data.shape[1]

  let embeddings = zeros_tensor([batch_size, seq_len, d_model])

  fold_range(0, batch_size, embeddings, fn(acc_b, b) -> {
    fold_range(0, seq_len, acc_b, fn(acc_s, s) -> {
      let token_idx = as_int(tensor_get_2d(token_ids, b, s))

      fold_range(0, d_model, acc_s, fn(acc_d, d) -> {
        let embed_val = tensor_get_2d(model.token_embed.data, token_idx, d)
        tensor_set_2d(acc_d, b, s, d, embed_val)
        acc_d
      })
    })
  })
}

// Get positional embeddings
function get_pos_embed(model: GPTModel, seq_len: Int) -> Tensor = {
  let d_model = model.pos_embed.data.shape[1]
  let pos_embeddings = zeros_tensor([1, seq_len, d_model])

  fold_range(0, seq_len, pos_embeddings, fn(acc_s, s) -> {
    fold_range(0, d_model, acc_s, fn(acc_d, d) -> {
      let pos_val = tensor_get_2d(model.pos_embed.data, s, d)
      tensor_set_2d(acc_d, 0, s, d, pos_val)
      acc_d
    })
  })
}

// GPT forward pass
function forward_gpt(model: GPTModel, token_ids: Tensor) -> Tensor = {
  let batch_size = token_ids.shape[0]
  let seq_len = token_ids.shape[1]

  // Get embeddings
  let token_embeddings = get_token_embed(model, token_ids)
  let pos_embeddings = get_pos_embed(model, seq_len)

  // Add embeddings (broadcast positional across batch)
  let x = tensor_add(token_embeddings, pos_embeddings)

  // Apply transformer blocks
  let x_after_blocks = fold_range(0, len(model.blocks), x, fn(acc, i) -> {
    let block = model.blocks[i]
    forward_block(block, acc)
  })

  // Final layer norm
  let x_norm = forward_layer_norm(model.ln_final, x_after_blocks)

  // LM head: [batch, seq_len, d_model] -> [batch, seq_len, vocab_size]
  let logits = forward_linear(model.lm_head, x_norm)

  logits
}

// ==================================================
// 6. UTILITY FUNCTIONS
// ==================================================

// GELU activation
function gelu(x: Tensor) -> Tensor = {
  let cdf_coeff = 0.7978845608028654
  let cubic_coeff = 0.044715

  let result_data = []
  let result = fold_range(0, x.size, result_data, fn(acc, i) -> {
    let val = x.data[i]
    let cubic = val * val * val
    let inner = val + (cubic_coeff * cubic)
    let cdf = 0.5 * (1.0 + math.tanh(cdf_coeff * inner))
    append(acc, val * cdf)
  })

  Tensor {
    data: result,
    shape: x.shape,
    strides: x.strides,
    ndim: x.ndim,
    size: x.size
  }
}

// ==================================================
// 7. TESTS
// ==================================================

function test_ffn_init() -> Bool = {
  let ffn = ffn_init(64, 42)
  ffn.fc1.out_features == 256 &&
  ffn.fc2.in_features == 256 &&
  ffn.fc2.out_features == 64
}

function test_transformer_block_init() -> Bool = {
  let block = transformer_block_init(64, 8, true, 42)
  block.mha.d_model == 64 &&
  block.mha.num_heads == 8 &&
  block.ffn.fc1.out_features == 256
}

function test_ffn_forward() -> Bool = {
  let ffn = ffn_init(32, 42)
  let x = ones_tensor([2, 4, 32])

  let output = forward_ffn(ffn, x)
  output.shape[0] == 2 && output.shape[1] == 4 && output.shape[2] == 32
}

function test_transformer_block_forward() -> Bool = {
  let block = transformer_block_init(64, 8, true, 42)
  let x = ones_tensor([2, 4, 64])

  let output = forward_block(block, x)
  output.shape[0] == 2 && output.shape[1] == 4 && output.shape[2] == 64
}

function test_gpt_config() -> Bool = {
  let config = GPTConfig {
    vocab_size: 50257,
    d_model: 768,
    num_heads: 12,
    num_layers: 12,
    max_seq_len: 1024
  }

  config.vocab_size == 50257 && config.num_layers == 12
}

function test_gpt_init() -> Bool = {
  let config = GPTConfig {
    vocab_size: 100,
    d_model: 64,
    num_heads: 4,
    num_layers: 2,
    max_seq_len: 256
  }

  let model = gpt_init(config, 42)
  len(model.blocks) == 2 &&
  model.token_embed.data.shape[0] == 100
}

function test_gpt_forward_shape() -> Bool = {
  let config = GPTConfig {
    vocab_size: 100,
    d_model: 64,
    num_heads: 4,
    num_layers: 2,
    max_seq_len: 256
  }

  let model = gpt_init(config, 42)
  let token_ids = zeros_tensor([2, 8])  // [batch=2, seq_len=8]
  let logits = forward_gpt(model, token_ids)

  logits.shape[0] == 2 && logits.shape[1] == 8 && logits.shape[2] == 100
}

function test_gpt_forward_single() -> Bool = {
  let config = GPTConfig {
    vocab_size: 50,
    d_model: 32,
    num_heads: 2,
    num_layers: 1,
    max_seq_len: 128
  }

  let model = gpt_init(config, 42)
  let token_ids = zeros_tensor([1, 4])
  let logits = forward_gpt(model, token_ids)

  logits.shape[0] == 1 && logits.shape[1] == 4 && logits.shape[2] == 50
}

function test_positional_embed() -> Bool = {
  let config = GPTConfig {
    vocab_size: 100,
    d_model: 64,
    num_heads: 4,
    num_layers: 1,
    max_seq_len: 256
  }

  let model = gpt_init(config, 42)
  let pos_embed = get_pos_embed(model, 8)

  pos_embed.shape[0] == 1 && pos_embed.shape[1] == 8 && pos_embed.shape[2] == 64
}

// ==================================================
// RUN ALL TESTS
// ==================================================

function run_all_tests() -> Bool = {
  let t1 = test_ffn_init()
  let t2 = test_transformer_block_init()
  let t3 = test_ffn_forward()
  let t4 = test_transformer_block_forward()
  let t5 = test_gpt_config()
  let t6 = test_gpt_init()
  let t7 = test_gpt_forward_shape()
  let t8 = test_gpt_forward_single()
  let t9 = test_positional_embed()

  t1 && t2 && t3 && t4 && t5 && t6 && t7 && t8 && t9
}

