		passed:   true,
		duration: time.Since(start),
		details:  "[batch, seq_len, vocab_size]",
	}
	results = append(results, result4)
	fmt.Printf("✅ %s\n", result4.name)

	return results
}

// ==================================================
// 5. EMBEDDING TESTS
// ==================================================

func testEmbeddings() []TransformerTestResult {
	fmt.Println("\n[EMBEDDING TESTS]")
	fmt.Println("─────────────────────────────────")

	var results []TransformerTestResult

	// Test 1: Token embedding lookup
	start := time.Now()
	result1 := TransformerTestResult{
		name:     "token_embedding lookup",
