// FreeLang GPT: Phase 6 - Training Loop
// ==================================================
// Loss, Optimizer, and Training Implementation
// Status: 🟢 Implementation (Phase 6 Final)

module trainer

import tensor
import transformer
import math
import arrays

// ==================================================
// 1. LOSS FUNCTIONS
// ==================================================

// Cross-entropy loss with softmax
// Input: logits [batch, seq_len, vocab_size]
//        targets [batch, seq_len] (token indices)
// Output: scalar loss
function cross_entropy_loss(logits: Tensor, targets: Tensor) -> Float = {
  let batch_size = logits.shape[0]
  let seq_len = logits.shape[1]
  let vocab_size = logits.shape[2]

  // Compute softmax + NLL
  let total_loss = fold_range(0, batch_size, 0.0, fn(acc_batch, b) -> {
    fold_range(0, seq_len, acc_batch, fn(acc_seq, s) -> {
      // Get target token
      let target_idx = as_int(tensor_get_2d(targets, b, s))

      // Get logits for this position [vocab_size]
      let max_logit = fold_range(0, vocab_size, -99999.0, fn(acc_max, v) -> {
        let logit = tensor_get_3d(logits, b, s, v)
        if logit > acc_max { logit } else { acc_max }
      })

      // Compute softmax denominator: sum(exp(logit - max))
      let exp_sum = fold_range(0, vocab_size, 0.0, fn(acc_sum, v) -> {
        let logit = tensor_get_3d(logits, b, s, v)
        let exp_logit = math.exp(logit - max_logit)
        acc_sum + exp_logit
      })

      // Compute -log(softmax[target])
      let target_logit = tensor_get_3d(logits, b, s, target_idx)
      let target_softmax = math.exp(target_logit - max_logit) / exp_sum
      let nll = -math.log(target_softmax + 1e-10)  // Add epsilon for stability

      acc_seq + nll
    })
  })

  // Average over batch and sequence
  let total_tokens = as_float(batch_size * seq_len)
  total_loss / total_tokens
}

// Accuracy metric
function compute_accuracy(logits: Tensor, targets: Tensor) -> Float = {
  let batch_size = logits.shape[0]
  let seq_len = logits.shape[1]
  let vocab_size = logits.shape[2]

  let correct = fold_range(0, batch_size, 0.0, fn(acc_batch, b) -> {
    fold_range(0, seq_len, acc_batch, fn(acc_seq, s) -> {
      // Get target
      let target_idx = as_int(tensor_get_2d(targets, b, s))

      // Find argmax prediction
      let max_logit = -99999.0
      let max_idx = 0
      let result = fold_range(0, vocab_size, (max_logit, max_idx), fn((m_logit, m_idx), v) -> {
        let logit = tensor_get_3d(logits, b, s, v)
        if logit > m_logit {
          (logit, v)
        } else {
          (m_logit, m_idx)
        }
      })

      let pred_idx = result.1

      // Check if correct
      let is_correct = if pred_idx == target_idx { 1.0 } else { 0.0 }
      acc_seq + is_correct
    })
  })

  let total_tokens = as_float(batch_size * seq_len)
  correct / total_tokens
}

// ==================================================
// 2. ADAM OPTIMIZER
// ==================================================

record AdamState {
  lr: Float,              // Learning rate
  beta1: Float,           // Exponential decay for mean (0.9)
  beta2: Float,           // Exponential decay for variance (0.999)
  eps: Float,             // Epsilon for numerical stability (1e-8)
  t: Int,                 // Timestep
  m: Array[Tensor],       // First moment (mean)
  v: Array[Tensor]        // Second moment (variance)
}

// Initialize Adam optimizer
function adam_init(lr: Float) -> AdamState = {
  AdamState {
    lr: lr,
    beta1: 0.9,
    beta2: 0.999,
    eps: 1e-8,
    t: 0,
    m: [],
    v: []
  }
}

// Adam optimization step for single parameter
// Assumes gradient already computed
