// ==================================================

// Cross-entropy loss with softmax
// Input: logits [batch, seq_len, vocab_size]
//        targets [batch, seq_len] (token indices)
// Output: scalar loss
function cross_entropy_loss(logits: Tensor, targets: Tensor) -> Float = {
  let batch_size = logits.shape[0]
  let seq_len = logits.shape[1]
  let vocab_size = logits.shape[2]

  // Compute softmax + NLL
  let total_loss = fold_range(0, batch_size, 0.0, fn(acc_batch, b) -> {
    fold_range(0, seq_len, acc_batch, fn(acc_seq, s) -> {
      // Get target token
      let target_idx = as_int(tensor_get_2d(targets, b, s))

      // Get logits for this position [vocab_size]
      let max_logit = fold_range(0, vocab_size, -99999.0, fn(acc_max, v) -> {
        let logit = tensor_get_3d(logits, b, s, v)
        if logit > acc_max { logit } else { acc_max }
      })

      // Compute softmax denominator: sum(exp(logit - max))
      let exp_sum = fold_range(0, vocab_size, 0.0, fn(acc_sum, v) -> {
        let logit = tensor_get_3d(logits, b, s, v)
        let exp_logit = math.exp(logit - max_logit)
        acc_sum + exp_logit
      })

      // Compute -log(softmax[target])
      let target_logit = tensor_get_3d(logits, b, s, target_idx)
      let target_softmax = math.exp(target_logit - max_logit) / exp_sum
      let nll = -math.log(target_softmax + 1e-10)  // Add epsilon for stability

      acc_seq + nll
    })
  })

  // Average over batch and sequence
  let total_tokens = as_float(batch_size * seq_len)
  total_loss / total_tokens
}

// Accuracy metric
function compute_accuracy(logits: Tensor, targets: Tensor) -> Float = {
  let batch_size = logits.shape[0]
