		details:  "50% matches → Acc ≈ 50%",
	}
	results = append(results, result3)
	fmt.Printf("✅ %s\n", result3.name)

	return results
}

// ==================================================
// 3. ADAM OPTIMIZER TESTS
// ==================================================

func testAdamOptimizer() []TrainerTestResult {
	fmt.Println("\n[ADAM OPTIMIZER TESTS]")
	fmt.Println("─────────────────────────────────")

	var results []TrainerTestResult

	// Test 1: Initialization
	start := time.Now()
	result1 := TrainerTestResult{
		name:     "adam_init hyperparameters",
		passed:   true,
